package dev.saathi.model;

import java.util.Collections;
import java.util.List;

/**
 * Complete, explainable output report generated by Saathi APK Intelligence.
 */
public class ApkAnalysisReport {
    private final String fileName;
    private final String sha256Checksum;
    private final long fileSizeBytes;
    private final ScanVerdict verdict;
    private final String summaryExplanation;
    private final String plainLanguageExplanation; // Senior-friendly, jargon-free
    private final List<ThreatIndicator> indicators;
    private final ManifestMetadata manifestMetadata;
    private final CertificateMetadata certificateMetadata;
    private final DexInspectionResult dexResult;
    private final List<String> recommendedActions;
    private final boolean canSafelyProceedWithInstall;

    public ApkAnalysisReport(
            String fileName,
            String sha256Checksum,
            long fileSizeBytes,
            ScanVerdict verdict,
            String summaryExplanation,
            String plainLanguageExplanation,
            List<ThreatIndicator> indicators,
            ManifestMetadata manifestMetadata,
            CertificateMetadata certificateMetadata,
            DexInspectionResult dexResult,
            List<String> recommendedActions,
            boolean canSafelyProceedWithInstall) {
        this.fileName = fileName;
        this.sha256Checksum = sha256Checksum;
        this.fileSizeBytes = fileSizeBytes;
        this.verdict = verdict;
        this.summaryExplanation = summaryExplanation;
        this.plainLanguageExplanation = plainLanguageExplanation;
        this.indicators = indicators != null ? indicators : Collections.emptyList();
        this.manifestMetadata = manifestMetadata;
        this.certificateMetadata = certificateMetadata;
        this.dexResult = dexResult;
        this.recommendedActions = recommendedActions != null ? recommendedActions : Collections.emptyList();
        this.canSafelyProceedWithInstall = canSafelyProceedWithInstall;
    }

    public String getFileName() {
        return fileName;
    }

    public String getSha256Checksum() {
        return sha256Checksum;
    }

    public long getFileSizeBytes() {
        return fileSizeBytes;
    }

    public ScanVerdict getVerdict() {
        return verdict;
    }

    public String getSummaryExplanation() {
        return summaryExplanation;
    }

    public String getPlainLanguageExplanation() {
        return plainLanguageExplanation;
    }

    public List<ThreatIndicator> getIndicators() {
        return indicators;
    }

    public ManifestMetadata getManifestMetadata() {
        return manifestMetadata;
    }

    public CertificateMetadata getCertificateMetadata() {
        return certificateMetadata;
    }

    public DexInspectionResult getDexResult() {
        return dexResult;
    }

    public List<String> getRecommendedActions() {
        return recommendedActions;
    }

    public boolean canSafelyProceedWithInstall() {
        return canSafelyProceedWithInstall;
    }
}
